func power(of base: Int, by exponent: Int) -> Int {
    var result = 1
    for _ in 1...exponent {
        result = result * base
    }
    return result
}

print(power(of: 2, by: 3))
print(power(of: 3, by: 2))

func line(_ text: String, times: Int = 2, separator: String = "-") -> String {
    var parts: [String] = []
    for _ in 1...times {
        parts.append(text)
    }
    return parts.joined(separator: separator)
}

print(line("ab"))
print(line("ab", times: 3))
print(line("ab", separator: "+"))

func split(_ total: Int, among people: Int) -> (each: Int, left: Int) {
    return (total / people, total % people)
}

